def run_batch(items):
    ok, idx, errors = [], [], []
    for i, x in enumerate(items):
        try:
            ok.append(validate(x))
            idx.append(i)
        except BadInput as e:
            errors.append((i, str(e)))
    results = model(ok) if ok else []
    out = [None] * len(items)
    for j, i in enumerate(idx):
        out[i] = {"ok": True, "value": results[j]}
    for i, msg in errors:
        out[i] = {"ok": False, "error": msg}
    return out

