import re

NAME_RE = re.compile(
    r"^(?P<model>[a-z0-9-]+)-v(?P<ver>\d+)-(?P<date>\d{8})-(?P<hash>[0-9a-f]{6})\.(?P<ext>\w+)$"
)


def parse(fn):
    m = NAME_RE.match(fn)
    if not m:
        return None
    d = m.groupdict()
    d["ver"] = int(d["ver"])
    return d


def conflicts(files):
    buckets = {}
    for fn in files:
        d = parse(fn)
        if not d:
            continue
        buckets.setdefault((d["model"], d["ver"], d["date"]), []).append(d["hash"])
    return {k: v for k, v in buckets.items() if len(set(v)) > 1}


def ordered(files):
    ds = [d for d in (parse(f) for f in files) if d]
    return sorted(ds, key=lambda d: (d["ver"], d["date"]))
